CREATE TABLE provider_oauth_states(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform_tenants(id) ON DELETE CASCADE,provider text NOT NULL CHECK(provider='VERCEL'),state_hash text NOT NULL UNIQUE,pkce_verifier_encrypted text NOT NULL,requested_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant_provider_connections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform_tenants(id) ON DELETE RESTRICT,provider text NOT NULL CHECK(provider='VERCEL'),status text NOT NULL CHECK(status IN('CONNECTED','REVOKED','ERROR')),access_token_encrypted text,external_account_id text,project_id text,project_name text,connected_by uuid REFERENCES users(id) ON DELETE RESTRICT,connected_at timestamptz,revoked_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider),CONSTRAINT provider_token_status CHECK((status='CONNECTED' AND access_token_encrypted IS NOT NULL) OR status<>'CONNECTED'));
CREATE INDEX provider_oauth_states_expiry_idx ON provider_oauth_states(expires_at) WHERE consumed_at IS NULL;
ALTER TABLE provider_oauth_states ENABLE ROW LEVEL SECURITY;ALTER TABLE tenant_provider_connections ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON provider_oauth_states,tenant_provider_connections FROM anon;END IF;IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON provider_oauth_states,tenant_provider_connections FROM authenticated;END IF;END $$;
